import assert from 'node:assert/strict';
import {chromium} from 'playwright';
const browser=await chromium.launch({headless:true});
try{for(const width of [1536,390,360]){const page=await browser.newPage({viewport:{width,height:900}});try{await page.goto('http://127.0.0.1:4173/',{waitUntil:'domcontentloaded'});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth+1),'homepage width '+width);const p=page.locator('#treasury-transparency');assert.equal(await p.locator('.actual-balance').count(),8);for(const el of await p.locator('.actual-balance').all())assert.equal(await el.innerText(),'Not deployed');assert.equal(await p.locator('a[href*="basescan.org/tx/"]').count(),0);assert.match(await p.locator('#treasury-movements').innerText(),/Unavailable/);await p.locator('a[href="/transparency/"]').click();assert.equal(new URL(page.url()).pathname,'/transparency/');assert.equal(await page.locator('#allocations details').count(),8);assert.match(await page.locator('#marketing').innerText(),/3,111,111\.108 CLIMB/);assert.match(await page.locator('#marketing').innerText(),/developer-controlled wallet/);assert.match(await page.locator('#supply').innerText(),/Not established/);assert.equal(await page.locator('.allocation-chart button').count(),8);await page.locator('.allocation-chart button').first().click();assert.equal(await page.locator('.allocation-chart button').first().getAttribute('aria-expanded'),'true');assert.ok(await page.locator('#allocations details').first().evaluate(e=>e.open));await page.locator('#month').fill('48');assert.match(await page.locator('#projection').innerText(),/100\.00% illustrative/);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.goto('http://127.0.0.1:4173/',{waitUntil:'domcontentloaded'});await p.locator('a[href="/governance/"]').click();assert.equal(new URL(page.url()).pathname,'/governance/');assert.equal(await page.locator('.board').count(),6);assert.ok(await page.locator('#forum-wallet').isDisabled());assert.match(await page.locator('body').innerText(),/Every interaction requires verified Base wallet sign-in/);assert.match(await page.locator('#proposals').innerText(),/require verified Base wallet sign-in/);assert.ok(await page.locator('#new-topic').isDisabled());assert.match(await page.locator('#proposals').innerText(),/NOT ACTIVE/);assert.ok(await page.locator('#topic-form').isHidden());assert.ok(await page.locator('#forum-feed').isHidden());assert.equal(await page.locator('script[src="/governance/forum.mjs"]').count(),1);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}finally{await page.close();}}}finally{await browser.close();}
